n&gt;&lt;span class=&quot;NormalTextRun SCXW23572186 BCX0&quot; data-ccp-charstyle=&quot;Calibri 11&quot;&gt;This role will serve as a point of contact for daily execution within the organization and work closely with Manufacturing, Operations, Quality, R&amp;amp;D, and Commercial to sustain production and help us take the next steps forward in our high-growth cycle&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW23572186 BCX0&quot; data-ccp-charstyle=&quot;Calibri 11&quot;&gt;.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW23572186 BCX0&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559738&amp;quot;:40,&amp;quot;335559739&amp;quot;:40,&amp;quot;335559740&amp;quot;:240,&amp;quot;335559991&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
